#!/usr/bin/env bash
# run_skew_matrix.sh — the REAL two-end skew matrix (issue #1197, part
# of #908 P0).
#
# Proves that a slice generated by the CURRENT generator compiles
# against BOTH ends of the supported core range:
#   - the OLDEST supported core: git tag v6.1.0 (materialized via
#     `git archive` into a temp dir — no checkout, no worktree)
#   - the NEWEST core: this checkout (master)
#
# Also proves the floor-stamped emission contract end to end:
#   - `--skin` generation against the OLD end is REFUSED with the skew
#     report (exit 1, `--> fix: dart pub upgrade zuraffa`) and writes
#     NO files;
#   - against the NEW end the surface exists and generation proceeds.
#
# No Flutter SDK needed: the generated legs are pure-Dart slices
# (entity + usecase + repository + datasource DI), analyzed with
# `dart analyze`. The Flutter-consumer gate (analyzer-family regular
# dep bumps, #1189) runs separately in CI — tools/flutter_consumer_smoke.sh.
#
# Usage:  tools/run_skew_matrix.sh
# Exit 0 iff every leg holds. CI: .github/workflows/skew-matrix.yaml
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

OLD_TAG="${SKEW_OLD_TAG:-v6.1.0}"
WORK="$(mktemp -d /tmp/zfa1197_matrix.XXXXXX)"
trap 'rm -rf "$WORK"' EXIT

echo "== skew matrix: generator=$(date -u +%FT%TZ) tag=$OLD_TAG work=$WORK"

# ---------------------------------------------------------------------------
# 1. Materialize the OLD core end (git archive — full history available in CI)
# ---------------------------------------------------------------------------
OLD_CORE="$WORK/old-core"
mkdir -p "$OLD_CORE"
git archive "$OLD_TAG" lib pubspec.yaml | tar -x -C "$OLD_CORE"
if [ ! -f "$OLD_CORE/lib/zuraffa.dart" ]; then
  echo "FATAL: $OLD_TAG materialization failed (no lib/zuraffa.dart)"; exit 2
fi
echo "old core: $OLD_CORE ($OLD_TAG, pubspec $(grep '^version:' "$OLD_CORE/pubspec.yaml" | awk '{print $2}'))"
if [ -f "$OLD_CORE/lib/skin.dart" ]; then
  echo "FATAL: $OLD_TAG unexpectedly exposes lib/skin.dart — update the matrix premise"; exit 2
fi

# ---------------------------------------------------------------------------
# 2. Consumer package skeleton (deps mirror a real generated app — the
#    entity goes through zorphy codegen, so the legs are full-fidelity)
# ---------------------------------------------------------------------------
make_consumer() {
  local core="$1" dest="$2"
  rm -rf "$dest"
  mkdir -p "$dest/lib"
  cat > "$dest/pubspec.yaml" <<YAML
name: skew_consumer
publish_to: none
environment:
  sdk: ^3.11.0
dependencies:
  zuraffa:
    path: $core
  zorphy_annotation: ^2.3.0
  meta: ^1.17.0
dev_dependencies:
  build_runner: ^2.15.2
  zorphy: ^2.3.0
  json_serializable: ^6.13.2
YAML
}

# AOT-compile the generator once from source (fast, deterministic).
echo "compiling generator..."
dart pub get --no-example >/dev/null 2>&1 || dart pub get --no-example
dart compile exe bin/zfa.dart -o "$WORK/zfa" >/dev/null 2>&1 || {
  echo "FATAL: generator compile failed"; exit 2; }

run_leg() {
  local core="$1" label="$2"
  local consumer="$WORK/consumer-$label"
  make_consumer "$core" "$consumer"
  echo "-- leg <$label>: core=$core"
  (cd "$consumer" && dart pub get >/dev/null 2>&1)

  # The pure-Dart slice: entity (with zorphy codegen) + usecase +
  # repository + datasource — the two-end-stable surface. NOTE: `di`
  # is deliberately NOT in the old-end slice: the datasource DI
  # registration files import package:zuraffa/simulation.dart (spec
  # 893), which is floor-registered — the [di-refusal] leg proves the
  # gate refuses it on the old end live.
  (cd "$consumer" && "$WORK/zfa" entity create -n Todo >/dev/null)
  (cd "$consumer" && dart run build_runner build >/dev/null 2>&1)
  (cd "$consumer" && "$WORK/zfa" make Todo \
      --methods=get,create \
      --with=repository,datasource,usecase >/dev/null)
  (cd "$consumer" && dart run build_runner build >/dev/null 2>&1)

  # Floor-stamped receipt proof (issue #1197).
  local receipt
  receipt="$(find "$consumer/.zfa/receipts" -name '*make-*.json' | head -1)"
  if [ -z "$receipt" ]; then
    echo "   FATAL: no make receipt written"; return 1
  fi
  python3 - "$receipt" <<'PY'
import json, sys
r = json.load(open(sys.argv[1]))
assert r.get('min_core_version'), f"receipt missing min_core_version: {r.get('min_core_version')}"
print(f"   receipt stamp ok: min_core_version={r['min_core_version']} generated_against_core={r.get('generated_against_core')}")
PY

  if (cd "$consumer" && dart analyze >/dev/null 2> "$WORK/analyze-$label.txt"); then
    echo "   dart analyze: CLEAN against $label core"
  else
    echo "   dart analyze: FAILED against $label core:" >&2
    sed -n '1,25p' "$WORK/analyze-$label.txt" >&2
    return 1
  fi
}

# ---------------------------------------------------------------------------
# 3. Skin refusal leg: OLD core lacks skin.dart → the gate refuses, exit 1,
#    no kit file written (the #1197 contract, live).
# ---------------------------------------------------------------------------
skin_refusal_leg() {
  local consumer="$WORK/consumer-skin-refusal"
  make_consumer "$OLD_CORE" "$consumer"
  (cd "$consumer" && dart pub get >/dev/null 2>&1)
  set +e
  (cd "$consumer" && "$WORK/zfa" skin kit --route home \
      > "$WORK/skin-kit.out" 2> "$WORK/skin-kit.err")
  local rc=$?
  set -e
  if [ $rc -eq 0 ]; then
    echo "-- leg [skin-refusal]: FATAL — skin kit emission was NOT refused on $OLD_TAG"; return 1
  fi
  cat "$WORK/skin-kit.out" "$WORK/skin-kit.err" \
    | grep -q "dart pub upgrade zuraffa" || {
    echo "-- leg [skin-refusal]: FATAL — refusal lacks the prescription:" >&2
    cat "$WORK/skin-kit.out" "$WORK/skin-kit.err" >&2; return 1; }
  if [ -f "$consumer/lib/src/skin/skin_contract_auditor.dart" ]; then
    echo "-- leg [skin-refusal]: FATAL — kit file written despite refusal"; return 1
  fi
  echo "-- leg [skin-refusal]: refused on $OLD_TAG (exit $rc) with prescription, no files written"
}

# DI refusal leg: the datasource DI files import
# package:zuraffa/simulation.dart (spec 893, post-v6.1.0) — on the OLD
# core the gate refuses the emission live (same contract as skin).
di_refusal_leg() {
  local consumer="$WORK/consumer-di-refusal"
  make_consumer "$OLD_CORE" "$consumer"
  (cd "$consumer" && dart pub get >/dev/null 2>&1)
  (cd "$consumer" && "$WORK/zfa" entity create -n Todo >/dev/null)
  (cd "$consumer" && dart run build_runner build >/dev/null 2>&1)
  set +e
  (cd "$consumer" && "$WORK/zfa" make Todo --methods=get,create \
      --with=repository,datasource,usecase,di \
      > "$WORK/di-refusal.out" 2> "$WORK/di-refusal.err")
  local rc=$?
  set -e
  if [ $rc -eq 0 ]; then
    echo "-- leg [di-refusal]: FATAL — simulation-coupled DI was NOT refused on $OLD_TAG"; return 1
  fi
  cat "$WORK/di-refusal.out" "$WORK/di-refusal.err" \
    | grep -q "dart pub upgrade zuraffa" || {
    echo "-- leg [di-refusal]: FATAL — refusal lacks the prescription:" >&2
    cat "$WORK/di-refusal.out" "$WORK/di-refusal.err" >&2; return 1; }
  echo "-- leg [di-refusal]: refused on $OLD_TAG (exit $rc) with prescription"
}

# Skin on the NEW end proceeds (master has the barrel) — generation only;
# compiling the Flutter kit is the CI flutter-smoke-gate's job.
skin_master_leg() {
  local consumer="$WORK/consumer-skin-master"
  make_consumer "$ROOT" "$consumer"
  (cd "$consumer" && dart pub get >/dev/null 2>&1)
  set +e
  (cd "$consumer" && "$WORK/zfa" skin kit --route home >/dev/null 2>&1)
  local rc=$?
  set -e
  if [ $rc -ne 0 ]; then
    echo "-- leg [skin-master]: FATAL — skin kit emission refused on master (exit $rc)"; return 1
  fi
  [ -f "$consumer/lib/src/skin/skin_contract_auditor.dart" ] || {
    echo "-- leg [skin-master]: FATAL — kit file missing after success"; return 1; }
  echo "-- leg [skin-master]: kit emitted on master (compile covered by flutter-smoke-gate)"
}

# ---------------------------------------------------------------------------
# 4. Run the matrix
# ---------------------------------------------------------------------------
FAILED=0
run_leg "$OLD_CORE" old        || FAILED=1
run_leg "$ROOT"     master     || FAILED=1
skin_refusal_leg               || FAILED=1
di_refusal_leg                 || FAILED=1
skin_master_leg                || FAILED=1

if [ $FAILED -ne 0 ]; then
  echo "== skew matrix: RED (see above)"; exit 1
fi
echo "== skew matrix: GREEN — slice compiles on both ends; floor gates live"
